import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2016-OCT-16 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2016-OCT-16 :: Ceph Performance Weekly","date":"2017-01-11T00:00:00.000Z","updated":"2017-01-12T00:00:00.000Z","tags":["Ceph","BlueStore","RocksDB","Performance Optimization","Memory Management"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.md"};function n(s,l,a,g,p,c){return i(),t("div",null,[...l[0]||(l[0]=[o("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Alan、Ben、Igor、Sage、Somnath等</p><p><strong>会议主题</strong>： Ceph社区近期工作进展及讨论</p><p><strong>一、关键进展</strong></p><ul><li><strong>内存管理</strong>： Alan提交了实现slab containers的PR，旨在减少内存碎片，并识别代码中存在的低效操作，从而更好地管理内存分配。</li><li><strong>BlueStore</strong>： <ul><li>Sage对BlueStore进行重构，预计将带来性能提升。</li><li>Igor开始为异步消息传递实现RDMA，这是XIO消息传递开发的一个替代方案。</li><li>优化了RocksDB的日志设置，可能对BlueStore产生积极影响。</li><li>移除了BlueStore的事务提交，提高了性能。</li><li>Sage进行了异步消息传递的性能优化，性能提升了40%。</li><li>PG级别的快照和事务性能得到提升。</li><li>BlueStore的紫色压缩设置和快速编码功能已合并。</li></ul></li><li><strong>RocksDB</strong>： <ul><li>Sage对RocksDB进行优化，减少了IO元数据更新的频率，提高了性能。</li><li>压缩设置已合并。</li></ul></li><li><strong>其他</strong>： <ul><li>RC锁定工作进展顺利。</li><li>Zipkin跟踪工作有望合并。</li><li>Slab容器工作继续进行。</li><li>Sandisk的ZetaScale集成工作取得进展，已在4K随机I/O方面超越了BlueStore。</li></ul></li></ul><p><strong>二、讨论的主要议题</strong></p><ul><li><strong>RocksDB行为</strong>： Sage对RocksDB的行为进行了深入研究，并分享了测试结果。结果表明，使用大缓冲区可以提高性能，尤其是在使用NVMe设备时。</li><li><strong>文件系统性能</strong>： Ben分享了使用Ceph BlueStore和RocksDB进行性能测试的结果，并提出了关于文件描述符限制的问题。</li><li><strong>ZetaScale</strong>： Sage介绍了Sandisk的ZetaScale集成工作，并分享了测试结果。</li></ul><p><strong>三、决定的事项</strong></p><ul><li>继续优化RocksDB和BlueStore。</li><li>对异步消息传递进行更多测试和评估。</li><li>对ZetaScale集成工作进行更多研究。</li></ul><p><strong>四、后续行动计划</strong></p><ul><li>Alan将进一步完善slab containers的PR。</li><li>Sage将继续优化RocksDB和BlueStore。</li><li>Ben将调查文件描述符限制问题。</li><li>Igor将继续开发RDMA异步消息传递。</li><li>Ben将分享更多性能测试结果。</li><li>Sage将分享更多关于ZetaScale集成工作的信息。</li></ul><p><strong>五、其他</strong></p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文原文的关键词，例如： <ul><li>slab containers</li><li>memory fragmentation</li><li>RDMA</li><li>async messenger</li><li>RocksDB</li><li>compaction</li><li>file descriptors</li><li>ZetaScale</li></ul></li></ul>",14)])])}const S=e(r,[["render",n]]);export{u as __pageData,S as default};
